(3156007, 441182, 66384, '<td valign="top">I don''t understand the title, but that doesn''t matter. It''s the image that counts. 7</td>', 'I don''t understand the title, but that doesn''t matter. It''s the image that counts. 7', '2006-12-28 11:57:14.000000', NULL, 1),
