(3156015, 441627, 66384, '<td valign="top">Very nice composition.</td>', 'Very nice composition.', '2006-12-28 12:00:09.000000', NULL, 1),
(3156018, 442373, 68947, '<td valign="top">Like the idea behind this shot.  Wish the battery could have been in focus more.  Would have really drove this home.</td>', 'Like the idea behind this shot.  Wish the battery could have been in focus more.  Would have really drove this home.', '2006-12-28 12:01:23.000000', NULL, 1),
(3156020, 440769, 66384, '<td valign="top">How did you do this lighting? It''s very nice.</td>', 'How did you do this lighting? It''s very nice.', '2006-12-28 12:02:02.000000', NULL, 1),
(3156028, 442708, 66384, '<td valign="top">I think the battery should be in sharp focus if it is the subject of the challenge and the photo.</td>', 'I think the battery should be in sharp focus if it is the subject of the challenge and the photo.', '2006-12-28 12:03:51.000000', NULL, 1),
(3156031, 441715, 68947, '<td valign="top">Very artsy shot!  Nicely done.  I wonder if cropping the top just a BIT more might have been a bit more powerful?????  The focus on the battery might have been a bit more powerful had there not been quite so much space above it. That''s about the only constructive critism I can give.  I really like it!</td>', 'Very artsy shot!  Nicely done.  I wonder if cropping the top just a BIT more might have been a bit more powerful?????  The focus on the battery might have been a bit more powerful had there not been quite so much space above it. That''s about the only constructive critism I can give.  I really like it!', '2006-12-28 12:04:24.000000', NULL, 1),
(3156035, 442909, 66384, '<td valign="top">Very amusing! and artistic. 9</td>', 'Very amusing! and artistic. 9', '2006-12-28 12:05:17.000000', NULL, 1),
