(3158436, 442373, 57570, '<td valign="top">The battery looks out of focus</td>', 'The battery looks out of focus', '2006-12-29 02:39:20.000000', NULL, 1),
(3158439, 442336, 57570, '<td valign="top">funny!! but lighting could have been better</td>', 'funny!! but lighting could have been better', '2006-12-29 02:40:38.000000', NULL, 1),
(3158443, 442724, 57570, '<td valign="top">batteries are lost and out of focus</td>', 'batteries are lost and out of focus', '2006-12-29 02:42:01.000000', NULL, 1),
(3158485, 442967, 69585, '<td valign="top">fantastic idea as shot!! 10</td>', 'fantastic idea as shot!! 10', '2006-12-29 03:14:23.000000', NULL, 1),
(3158515, 442555, 51653, '<td valign="top">I do not perceive the AAA battery as an intruder, but as a noisy element.<br/>Maybe a different batteries disposition or a wider DOF to have it well focused could improve the shot.</td>', 'I do not perceive the AAA battery as an intruder, but as a noisy element.Maybe a different batteries disposition or a wider DOF to have it well focused could improve the shot.', '2006-12-29 04:19:27.000000', NULL, 1),
(3158518, 442976, 51653, '<td valign="top">I do not find something really interesting in this shot. I think it is mainly due to the cutt shadow.</td>', 'I do not find something really interesting in this shot. I think it is mainly due to the cutt shadow.', '2006-12-29 04:21:12.000000', NULL, 1),
(3158519, 440900, 51653, '<td valign="top">I do not find an interesting point to concentrate on in this shot. The batteries could be the right one, but the hard contrasts on the vertical one and its central position distracts me.</td>', 'I do not find an interesting point to concentrate on in this shot. The batteries could be the right one, but the hard contrasts on the vertical one and its central position distracts me.', '2006-12-29 04:23:43.000000', NULL, 1),
(3158520, 442663, 51653, '<td valign="top">It is well focused and the limited DOF correctly drive my attention on the main subject, but I still do not find it interesting enough. Maybe a different composition or a more interesting bg could improve the shot.</td>', 'It is well focused and the limited DOF correctly drive my attention on the main subject, but I still do not find it interesting enough. Maybe a different composition or a more interesting bg could improve the shot.', '2006-12-29 04:26:03.000000', NULL, 1),
(3158523, 442990, 51653, '<td valign="top">I find it quite confusing, sorry.</td>', 'I find it quite confusing, sorry.', '2006-12-29 04:27:15.000000', NULL, 1),
(3158524, 443000, 51653, '<td valign="top">Sorry, but it seems quite out of focus.</td>', 'Sorry, but it seems quite out of focus.', '2006-12-29 04:27:22.000000', NULL, 1),
(3158526, 442391, 51653, '<td valign="top">A funny idea, but I''m finding hard to appreciate this shot, mainly for the too tight crop. IMO it would be really better with some more space on the right and below the subject.</td>', 'A funny idea, but I''m finding hard to appreciate this shot, mainly for the too tight crop. IMO it would be really better with some more space on the right and below the subject.', '2006-12-29 04:29:05.000000', NULL, 1),
(3158531, 442496, 51653, '<td valign="top">Interesting composition, but IMO the out of focus fg is quite annoying. <br/> <br/>You have also a lot of noise that is really distracting (at the first glance I was more concerned of the noise than of the shot).</td>', 'Interesting composition, but IMO the out of focus fg is quite annoying.  You have also a lot of noise that is really distracting (at the first glance I was more concerned of the noise than of the shot).', '2006-12-29 04:33:48.000000', NULL, 1),
(3158533, 441100, 51653, '<td valign="top">IMO it is too soft, some sharpening could help.</td>', 'IMO it is too soft, some sharpening could help.', '2006-12-29 04:34:34.000000', NULL, 1),
(3158670, 442811, 47842, '<td valign="top">looks like its a broken glass, is it broken actually? :) nice water and nice title. a brighter picture with a bit more contrast would have suited my taste better.</td>', 'looks like its a broken glass, is it broken actually? :) nice water and nice title. a brighter picture with a bit more contrast would have suited my taste better.', '2006-12-29 05:50:42.000000', NULL, 1),
(3158852, 442939, 66635, '<td valign="top">Very well done.  I like the background.</td>', 'Very well done.  I like the background.', '2006-12-29 08:29:50.000000', NULL, 1),
(3158856, 442899, 65125, '<td valign="top">Great photo, i love the water.</td>', 'Great photo, i love the water.', '2006-12-29 08:30:06.000000', NULL, 1),
(3158859, 441715, 65125, '<td valign="top">Nice background and lightning. I like it a lot.</td>', 'Nice background and lightning. I like it a lot.', '2006-12-29 08:30:31.000000', NULL, 1),
(3158860, 442909, 65125, '<td valign="top">Fantastic idea.</td>', 'Fantastic idea.', '2006-12-29 08:30:42.000000', NULL, 1),
