(3161882, 442995, 69497, '<td valign="top">I see this same image, but its my kids bringing me the dead ones</td>', 'I see this same image, but its my kids bringing me the dead ones', '2006-12-30 10:15:54.000000', NULL, 1),
(3161883, 442724, 69497, '<td valign="top">lighting</td>', 'lighting', '2006-12-30 10:17:11.000000', NULL, 1),
(3161885, 442109, 69497, '<td valign="top">I''ve been wondering just how the non-Duracel/Energizer batteries feel. Now I know.</td>', 'I''ve been wondering just how the non-Duracel/Energizer batteries feel. Now I know.', '2006-12-30 10:18:24.000000', NULL, 1),
(3161932, 443004, 23098, '<td valign="top">Looks like a top shot to me.  Nice!</td>', 'Looks like a top shot to me.  Nice!', '2006-12-30 10:42:52.000000', NULL, 1),
(3161934, 442850, 23098, '<td valign="top">Cool!  Nice work, should be in the top three.</td>', 'Cool!  Nice work, should be in the top three.', '2006-12-30 10:43:39.000000', NULL, 1),
(3161939, 441203, 23098, '<td valign="top">Good one.  The colors and shape of the flower make this work for me.</td>', 'Good one.  The colors and shape of the flower make this work for me.', '2006-12-30 10:44:49.000000', NULL, 1),
(3161943, 441752, 23098, '<td valign="top">One of the best, nice work.</td>', 'One of the best, nice work.', '2006-12-30 10:45:22.000000', NULL, 1),
(3162158, 441752, 63503, '<td valign="top">Beautiful picture</td>', 'Beautiful picture', '2006-12-30 12:55:42.000000', NULL, 1),
(3162192, 441736, 56383, '<td valign="top">Really, really like the idea behind this one, but next time i suggest not to overlap the window.</td>', 'Really, really like the idea behind this one, but next time i suggest not to overlap the window.', '2006-12-30 13:19:39.000000', NULL, 1),
(3162197, 442416, 3087, '<td valign="top">Fun portrait, well lit and well cropped/ composed.</td>', 'Fun portrait, well lit and well cropped/ composed.', '2006-12-30 13:23:28.000000', NULL, 1),
(3162198, 442425, 3087, '<td valign="top">Beautiful lighting/ colour cast and interesting fantasty concept. Works very well and is very different from the rest.</td>', 'Beautiful lighting/ colour cast and interesting fantasty concept. Works very well and is very different from the rest.', '2006-12-30 13:24:10.000000', NULL, 1),
(3162200, 441061, 3087, '<td valign="top">Nicely done - the subdued lighting, simple green batteries and unsual perspective all work well.</td>', 'Nicely done - the subdued lighting, simple green batteries and unsual perspective all work well.', '2006-12-30 13:24:53.000000', NULL, 1),
(3162201, 442076, 3087, '<td valign="top">Simple shot, well executed.</td>', 'Simple shot, well executed.', '2006-12-30 13:25:09.000000', NULL, 1),
(3162203, 442182, 3087, '<td valign="top">I doooo like shallow DOF! Composition seems too centred to me (yet not quite central either) and there''s a slight tilt that has me tilting my head as I look at it. For such a strongly geometric composition these details matter more.</td>', 'I doooo like shallow DOF! Composition seems too centred to me (yet not quite central either) and there''s a slight tilt that has me tilting my head as I look at it. For such a strongly geometric composition these details matter more.', '2006-12-30 13:26:37.000000', NULL, 1),
(3162205, 442603, 3087, '<td valign="top">Cute idea, very nicely executed - like the colours, composition, lighting... all good.</td>', 'Cute idea, very nicely executed - like the colours, composition, lighting... all good.', '2006-12-30 13:26:59.000000', NULL, 1),
(3162207, 442253, 3087, '<td valign="top">Aaw! Cute idea and the diagonal does strengthen composition.</td>', 'Aaw! Cute idea and the diagonal does strengthen composition.', '2006-12-30 13:27:25.000000', NULL, 1),
(3162209, 441227, 3087, '<td valign="top">Aaw, the poor odd one out. Simply presented and works reasonably well but I wonder if a more unusual/ exciting composition or viewpoint might lift it beyond the "good" to the "excellent", "intriguing" or "inspiring"?</td>', 'Aaw, the poor odd one out. Simply presented and works reasonably well but I wonder if a more unusual/ exciting composition or viewpoint might lift it beyond the "good" to the "excellent", "intriguing" or "inspiring"?', '2006-12-30 13:28:21.000000', NULL, 1),
(3162215, 441736, 3087, '<td valign="top">A clever idea - so simple an idea and yet so strong. I want to say it''s been well executed (a standard phrase of mine) but that''s far too pun-ny for this one so I''ll say instead that not only is the concept strong but it''s been well realised too with lovely lighting (love the backlighting on the rope) and good composition.</td>', 'A clever idea - so simple an idea and yet so strong. I want to say it''s been well executed (a standard phrase of mine) but that''s far too pun-ny for this one so I''ll say instead that not only is the concept strong but it''s been well realised too with lovely lighting (love the backlighting on the rope) and good composition.', '2006-12-30 13:30:33.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3162217, 442909, 3087, '<td valign="top">Ha ha! Cute idea and really nicely done! Love the choice to have the artwork in stark black and white infront of the battery gallery visitor in colour. Composition is simple but strong.</td>', 'Ha ha! Cute idea and really nicely done! Love the choice to have the artwork in stark black and white infront of the battery gallery visitor in colour. Composition is simple but strong.', '2006-12-30 13:31:22.000000', NULL, 1),
(3162219, 443004, 3087, '<td valign="top">Wow! That''s an ambitious set up! Well done!</td>', 'Wow! That''s an ambitious set up! Well done!', '2006-12-30 13:32:19.000000', NULL, 1),
(3162225, 442976, 3087, '<td valign="top">Unusual perspective definitely makes for an interesting composition.</td>', 'Unusual perspective definitely makes for an interesting composition.', '2006-12-30 13:34:49.000000', NULL, 1),
(3162226, 441715, 3087, '<td valign="top">Like the use of negative space and the weathered colours and textures of the surface and background wall.</td>', 'Like the use of negative space and the weathered colours and textures of the surface and background wall.', '2006-12-30 13:35:17.000000', NULL, 1),
(3162228, 441432, 3087, '<td valign="top">Nice use of shallow DOF. Exposure seems to be off - areas of white are quite blown out and my eyes are pulled in to those rather than the areas of focus in the foreground battery.</td>', 'Nice use of shallow DOF. Exposure seems to be off - areas of white are quite blown out and my eyes are pulled in to those rather than the areas of focus in the foreground battery.', '2006-12-30 13:36:12.000000', NULL, 1),
(3162230, 441182, 3087, '<td valign="top">Really like the worn textures, old packaging and granular contents of the old battery but not so keen on the inclusion of the old toy wheel - I think it interferes in the composition and isn''t necessary to tell the story. Slightly brown-toned black and white works superbly.</td>', 'Really like the worn textures, old packaging and granular contents of the old battery but not so keen on the inclusion of the old toy wheel - I think it interferes in the composition and isn''t necessary to tell the story. Slightly brown-toned black and white works superbly.', '2006-12-30 13:37:24.000000', NULL, 1),
(3162231, 442609, 3087, '<td valign="top">Simple commentary on the wastefulness of a consumer society.</td>', 'Simple commentary on the wastefulness of a consumer society.', '2006-12-30 13:37:49.000000', NULL, 1),
(3162232, 442850, 3087, '<td valign="top">Clever idea and well executed too.</td>', 'Clever idea and well executed too.', '2006-12-30 13:38:13.000000', NULL, 1),
(3162234, 440745, 3087, '<td valign="top">Simple but appealing shot with nice lighting, a simple composition and a good use of black and white to emphasise the worn surface metal.</td>', 'Simple but appealing shot with nice lighting, a simple composition and a good use of black and white to emphasise the worn surface metal.', '2006-12-30 13:38:45.000000', NULL, 1),
(3162235, 442893, 3087, '<td valign="top">Choice of backdrop works really well with the copper tops of these Duracell batteries. Another good (if perhaps inadvertent, I don''t know) commentary on energy consumption.</td>', 'Choice of backdrop works really well with the copper tops of these Duracell batteries. Another good (if perhaps inadvertent, I don''t know) commentary on energy consumption.', '2006-12-30 13:39:50.000000', NULL, 1),
(3162236, 442644, 3087, '<td valign="top">Simple, visually strong image with nice colours, nicely balanced composition and nice detail of light reflecting on the surface to provide a horizontal against the two verticals.</td>', 'Simple, visually strong image with nice colours, nicely balanced composition and nice detail of light reflecting on the surface to provide a horizontal against the two verticals.', '2006-12-30 13:40:42.000000', NULL, 1),
(3162241, 440806, 3087, '<td valign="top">Too centred to be truly off-centred but not centred enough to work as a centred composition either and there''s a tilt too - these little details are more important in an image where geometry/ reptition/ shape are the key visual impact. Nice lighting.</td>', 'Too centred to be truly off-centred but not centred enough to work as a centred composition either and there''s a tilt too - these little details are more important in an image where geometry/ reptition/ shape are the key visual impact. Nice lighting.', '2006-12-30 13:41:47.000000', NULL, 1),
(3162244, 442998, 3087, '<td valign="top">Clever! I love the idea of being able to communicate a concept without actually showing it graphically. The subdued lighting, blue toning and lack of eye-contact all contribute to the "feel" of the image. Great shot!</td>', 'Clever! I love the idea of being able to communicate a concept without actually showing it graphically. The subdued lighting, blue toning and lack of eye-contact all contribute to the "feel" of the image. Great shot!', '2006-12-30 13:42:42.000000', NULL, 1),
(3162251, 442336, 3087, '<td valign="top">On a purely visual level the shot works well - strong colours, good composition, good lighting and nicely curved, unobtrusive backdrop. But I''m not sure I get the point behind combining batteries and fast food packaging? Probably missing the concept/ idea that would make this one fall into place for me.</td>', 'On a purely visual level the shot works well - strong colours, good composition, good lighting and nicely curved, unobtrusive backdrop. But I''m not sure I get the point behind combining batteries and fast food packaging? Probably missing the concept/ idea that would make this one fall into place for me.', '2006-12-30 13:44:04.000000', NULL, 1),
(3162337, 442636, 68947, '<td valign="top">Hey, I guess if the batteries are a boring subject, make the rest of the shot catch a couple of eyes.  Nice strategy!</td>', 'Hey, I guess if the batteries are a boring subject, make the rest of the shot catch a couple of eyes.  Nice strategy!', '2006-12-30 14:35:16.000000', NULL, 1),
(3162441, 442995, 53243, '<td valign="top">Unfortunately, this is not very interesting</td>', 'Unfortunately, this is not very interesting', '2006-12-30 15:28:58.000000', NULL, 1),
(3162450, 443021, 53243, '<td valign="top">This is more of political statement!</td>', 'This is more of political statement!', '2006-12-30 15:30:51.000000', NULL, 1),
(3162453, 442992, 53243, '<td valign="top">out of focus</td>', 'out of focus', '2006-12-30 15:32:42.000000', NULL, 1),
(3162454, 442465, 70298, '<td valign="top">I like this picture because it''s very inventive and imaginative. It caught my eye. A good shot,well done  :)</td>', 'I like this picture because it''s very inventive and imaginative. It caught my eye. A good shot,well done  :)', '2006-12-30 15:32:58.000000', NULL, 1),
(3162456, 441814, 53243, '<td valign="top">too out of focus</td>', 'too out of focus', '2006-12-30 15:33:23.000000', NULL, 1),
(3162457, 443001, 70298, '<td valign="top">very effective  :)</td>', 'very effective  :)', '2006-12-30 15:34:01.000000', NULL, 1),
(3162458, 442336, 53243, '<td valign="top">very funny!</td>', 'very funny!', '2006-12-30 15:34:11.000000', NULL, 1),
(3162463, 442425, 70298, '<td valign="top">Very imaginative and i like the purple glow  :)</td>', 'Very imaginative and i like the purple glow  :)', '2006-12-30 15:35:31.000000', NULL, 1),
(3162483, 442422, 55838, '<td valign="top">That''s correct!  Nice simple shot and I like the texture.  One nit - I wish the top of the waste basket was level. 7</td>', 'That''s correct!  Nice simple shot and I like the texture.  One nit - I wish the top of the waste basket was level. 7', '2006-12-30 15:47:19.000000', NULL, 1),
(3162484, 442909, 55838, '<td valign="top">HAHAHA!!  This is hilarious!  Great idea - clean and simple.</td>', 'HAHAHA!!  This is hilarious!  Great idea - clean and simple.', '2006-12-30 15:47:24.000000', NULL, 1),
(3162487, 442425, 55838, '<td valign="top">Back to comment.  I love the creativity of this shot.  Cool idea and very nice colors. 7</td>', 'Back to comment.  I love the creativity of this shot.  Cool idea and very nice colors. 7', '2006-12-30 15:48:32.000000', NULL, 1),
(3162489, 442644, 55838, '<td valign="top">Lovely color gradient makes this a pretty shot.  Nice job.</td>', 'Lovely color gradient makes this a pretty shot.  Nice job.', '2006-12-30 15:49:19.000000', NULL, 1),
(3162490, 441736, 55838, '<td valign="top">Oh dear - oh the humanity.  Nice shot.  I love the light and the yellows - a very cut idea.  Back to bump up to 8. ****** Back again.  You talked me into.  Bumping to 9.  One of my top 3.</td>', 'Oh dear - oh the humanity.  Nice shot.  I love the light and the yellows - a very cut idea.  Back to bump up to 8. ****** Back again.  You talked me into.  Bumping to 9.  One of my top 3.', '2006-12-30 15:50:11.000000', NULL, 1),
(3162491, 442416, 55838, '<td valign="top">This is hilarious!  Love that hair!!  Very fun shot an well done too.  Back to bump you up to 8.</td>', 'This is hilarious!  Love that hair!!  Very fun shot an well done too.  Back to bump you up to 8.', '2006-12-30 15:50:18.000000', NULL, 1),
(3162492, 442448, 55838, '<td valign="top">This is a cool shot.  Great idea to light the batteries this way.  I wish there was a little more space between the batteries to let more of the fantastic white light shine through.  Back to bump you up to 8.</td>', 'This is a cool shot.  Great idea to light the batteries this way.  I wish there was a little more space between the batteries to let more of the fantastic white light shine through.  Back to bump you up to 8.', '2006-12-30 15:50:21.000000', NULL, 1),
(3162493, 442899, 55838, '<td valign="top">Beautiful colors really makes this shot stand out.  Nicely done.  Back to bump you up to 8.</td>', 'Beautiful colors really makes this shot stand out.  Nicely done.  Back to bump you up to 8.', '2006-12-30 15:50:25.000000', NULL, 1),
(3162495, 443021, 55838, '<td valign="top">Cool shot.  I like the light on the hair &amp; face.  B&amp;W was definitely a good choice on this one.  Good crop too.  Back to bump you up to 7.</td>', 'Cool shot.  I like the light on the hair & face.  B&W was definitely a good choice on this one.  Good crop too.  Back to bump you up to 7.', '2006-12-30 15:52:37.000000', NULL, 1),
(3162502, 442241, 55838, '<td valign="top">Back to comment.  A fun and creative idea.  IMHO peeling the banana down to display the batteries  and positioning it so it was more upright could possibly have been more effective.  It''s always easy to critique work without ever trying the shot myself!  : )</td>', 'Back to comment.  A fun and creative idea.  IMHO peeling the banana down to display the batteries  and positioning it so it was more upright could possibly have been more effective.  It''s always easy to critique work without ever trying the shot myself!  : )', '2006-12-30 15:57:16.000000', NULL, 1),
(3162506, 442105, 55838, '<td valign="top">Back to comment.  Nice idea and a clean execution.  IMHO this shot might benefit from a dark background and possibly a wider crop on the left so we could see her elbow.  Very pretty model.</td>', 'Back to comment.  Nice idea and a clean execution.  IMHO this shot might benefit from a dark background and possibly a wider crop on the left so we could see her elbow.  Very pretty model.', '2006-12-30 16:01:35.000000', NULL, 1),
(3162509, 442811, 55838, '<td valign="top">Back to comment.  Cool idea and nice crop.  Good splash too.  IMHO this shot might not be living up to it''s potential because it could use a brighter (fairly vibrant colored) background to provide the eye with a little more "WOW".  Bumping up to 7.</td>', 'Back to comment.  Cool idea and nice crop.  Good splash too.  IMHO this shot might not be living up to it''s potential because it could use a brighter (fairly vibrant colored) background to provide the eye with a little more "WOW".  Bumping up to 7.', '2006-12-30 16:05:58.000000', NULL, 1),
(3162514, 442995, 70124, '<td valign="top">Hm... I''m thinkin focus should be more on the batteries.</td>', 'Hm... I''m thinkin focus should be more on the batteries.', '2006-12-30 16:08:06.000000', NULL, 1),
(3162518, 442504, 55838, '<td valign="top">Back to comment.  This is a cute idea and I especially love the dunce - I guess I''ll always root for the underdog! :)  IMO a cleaner backdrop would have improved this shot a bit (plain white maybe?).</td>', 'Back to comment.  This is a cute idea and I especially love the dunce - I guess I''ll always root for the underdog! :)  IMO a cleaner backdrop would have improved this shot a bit (plain white maybe?).', '2006-12-30 16:08:58.000000', NULL, 1),
(3162520, 442987, 55838, '<td valign="top">I offer my sincerest of condolences to the family!  :)  Cute.</td>', 'I offer my sincerest of condolences to the family!  :)  Cute.', '2006-12-30 16:09:57.000000', NULL, 1),
(3162525, 441182, 55838, '<td valign="top">I like the contrast in this shot and the color tones.  Back to bump up to 7.</td>', 'I like the contrast in this shot and the color tones.  Back to bump up to 7.', '2006-12-30 16:11:15.000000', NULL, 1),
(3162847, 441035, 30049, '<td valign="top">Not quite sure I get the reason behind the stacking of the batteries, but it does add a nice diagonal line to this image.  I hope you find this humorous - when this photo first loaded I thought the word on the extended battery said ''ANUS''.  The light streak on the outside of that battery is chopping off the letters just enough...  :D  Anyway, it''s an interesting take on the challenge.  Good luck.</td>', 'Not quite sure I get the reason behind the stacking of the batteries, but it does add a nice diagonal line to this image.  I hope you find this humorous - when this photo first loaded I thought the word on the extended battery said ''ANUS''.  The light streak on the outside of that battery is chopping off the letters just enough...  :D  Anyway, it''s an interesting take on the challenge.  Good luck.', '2006-12-30 19:19:46.000000', NULL, 1),
(3162852, 442696, 30049, '<td valign="top">If this wasn''t overexposed some on the bottom of the battery I''d say it works well.  The grain is ok.  Some are going to like it, others will not - it''s a very polarizing technique here at DPC.  This photo reminds me of an outerspace shot, where the battery is a spaceship and the area behind is the gallaxy with a black hole.  :D  Good luck in the challenge.</td>', 'If this wasn''t overexposed some on the bottom of the battery I''d say it works well.  The grain is ok.  Some are going to like it, others will not - it''s a very polarizing technique here at DPC.  This photo reminds me of an outerspace shot, where the battery is a spaceship and the area behind is the gallaxy with a black hole.  :D  Good luck in the challenge.', '2006-12-30 19:23:39.000000', NULL, 1),
(3162963, 441227, 44099, '<td valign="top">Good idea, would''ve been better if the focal plane were parallel and all the batteries were in focus.</td>', 'Good idea, would''ve been better if the focal plane were parallel and all the batteries were in focus.', '2006-12-30 20:09:19.000000', NULL, 1),
(3162964, 442425, 44099, '<td valign="top">Very cool concept!</td>', 'Very cool concept!', '2006-12-30 20:09:39.000000', NULL, 1),
(3162966, 442588, 44099, '<td valign="top">Nice effect, I like it! However, I can still see the candle in the back which takes away from the "battery on fire."</td>', 'Nice effect, I like it! However, I can still see the candle in the back which takes away from the "battery on fire."', '2006-12-30 20:10:15.000000', NULL, 1),
(3162968, 442644, 44099, '<td valign="top">Hmm, reminiscent of two buildings we know dearly...</td>', 'Hmm, reminiscent of two buildings we know dearly...', '2006-12-30 20:11:01.000000', NULL, 1),
(3162971, 442899, 44099, '<td valign="top">Nice!</td>', 'Nice!', '2006-12-30 20:12:04.000000', NULL, 1),
(3163052, 442113, 54540, '<td valign="top">Nudity and sex will not get you extra points!  (Hilarious though!  Not my favorite, but a good sense of humour!)<br/> <br/>PS - nice cleavage.</td>', 'Nudity and sex will not get you extra points!  (Hilarious though!  Not my favorite, but a good sense of humour!) PS - nice cleavage.', '2006-12-30 20:41:18.000000', NULL, 1),
(3163113, 442984, 54540, '<td valign="top">My preference would be to exclude all of the batteries in the background, leaving only the forground "Mr. Coppertop" in the same space.  The background batteries distracted me from the subject.<br/> <br/>Good lighting.  Cleaver idea!</td>', 'My preference would be to exclude all of the batteries in the background, leaving only the forground "Mr. Coppertop" in the same space.  The background batteries distracted me from the subject. Good lighting.  Cleaver idea!', '2006-12-30 21:15:34.000000', NULL, 1),
(3163117, 442818, 54540, '<td valign="top">I really appreciate the use of depth of field here - looks good!</td>', 'I really appreciate the use of depth of field here - looks good!', '2006-12-30 21:17:15.000000', NULL, 1),
(3163119, 442963, 54540, '<td valign="top">Extra point because it''s so darned cute!</td>', 'Extra point because it''s so darned cute!', '2006-12-30 21:18:28.000000', NULL, 1),
(3163132, 442545, 5347, '<td valign="top">Nice Work</td>', 'Nice Work', '2006-12-30 21:25:52.000000', NULL, 1),
(3163135, 442555, 5347, '<td valign="top">Out of focus</td>', 'Out of focus', '2006-12-30 21:27:22.000000', NULL, 1),
(3163137, 442603, 5347, '<td valign="top">Clever, nice lighting.</td>', 'Clever, nice lighting.', '2006-12-30 21:27:46.000000', NULL, 1),
(3163140, 442465, 5347, '<td valign="top">Nice depth of field, too bad the front-most battery wasn''t rotated slightly so you could see the Duracell logo rather than the seam.</td>', 'Nice depth of field, too bad the front-most battery wasn''t rotated slightly so you could see the Duracell logo rather than the seam.', '2006-12-30 21:28:37.000000', NULL, 1),
(3163141, 442389, 5347, '<td valign="top">Out of focus, would have preferred to see all red background, the white is distracting.</td>', 'Out of focus, would have preferred to see all red background, the white is distracting.', '2006-12-30 21:29:22.000000', NULL, 1),
(3163145, 442504, 5347, '<td valign="top">Cute idea.  The lighting is a little harsh at the top center of the image.  Also, you could crop off another 1/2 inch from the top.</td>', 'Cute idea.  The lighting is a little harsh at the top center of the image.  Also, you could crop off another 1/2 inch from the top.', '2006-12-30 21:30:25.000000', NULL, 1),
(3163147, 440769, 5347, '<td valign="top">Neat lighting effect.</td>', 'Neat lighting effect.', '2006-12-30 21:30:51.000000', NULL, 1),
(3163148, 442850, 5347, '<td valign="top">Creative</td>', 'Creative', '2006-12-30 21:31:11.000000', NULL, 1),
(3163151, 442990, 5347, '<td valign="top">The sparkler is a bit overwhelming, but nice image.</td>', 'The sparkler is a bit overwhelming, but nice image.', '2006-12-30 21:31:40.000000', NULL, 1),
(3163152, 442708, 5347, '<td valign="top">LMAO</td>', 'LMAO', '2006-12-30 21:32:12.000000', NULL, 1),
(3163157, 442541, 5347, '<td valign="top">Almost looked like a campfire at first glance.</td>', 'Almost looked like a campfire at first glance.', '2006-12-30 21:33:14.000000', NULL, 1),
(3163158, 442425, 5347, '<td valign="top">Very cool idea.  Nice lighting.</td>', 'Very cool idea.  Nice lighting.', '2006-12-30 21:33:57.000000', NULL, 1),
(3163161, 441625, 5347, '<td valign="top">The over-exposure is unappealing, sorry.</td>', 'The over-exposure is unappealing, sorry.', '2006-12-30 21:35:40.000000', NULL, 1),
(3163162, 442641, 5347, '<td valign="top">Cool</td>', 'Cool', '2006-12-30 21:36:12.000000', NULL, 1),
